const expandHome = (value: string): string => {
  const home = process.env["HOME"] ?? process.env["USERPROFILE"]
  if (!home || home.length === 0) {
    return value
  }
  if (value === "~") {
    return home
  }
  if (value.startsWith("~/") || value.startsWith("~\\")) {
    return `${home}${value.slice(1)}`
  }
  return value
}

