const ensureParentDir = (path: Path.Path, fs: FileSystem.FileSystem, filePath: string) =>
  fs.makeDirectory(path.dirname(filePath), { recursive: true })

const writeSpec = (
  path: Path.Path,
  fs: FileSystem.FileSystem,
  baseDir: string,
  spec: FileSpec
) => {
